const urls = new Map();
const hits = new Map();

const ALPHABET = 'abcdefghijklmnopqrstuvwxyz0123456789';
const CODE_LENGTH = 6;
const MAX_URL_LENGTH = 2048;
const MAX_HITS_PER_CODE = 1000;

export function createCode() {
  let code = '';
  for (let i = 0; i < CODE_LENGTH; i++) {
    code += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
  }
  return code;
}

/** Throws on anything that is not a plausible http(s) URL. */
export function validateUrl(value) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error('url must be a non-empty string');
  }
  if (value.length > MAX_URL_LENGTH) {
    throw new Error(`url must be at most ${MAX_URL_LENGTH} characters`);
  }
  let parsed;
  try {
    parsed = new URL(value);
  } catch {
    throw new Error('url is not a valid URL');
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new Error('url must use http or https');
  }
  return parsed.toString();
}

export function shorten(url) {
  const normalised = validateUrl(url);

  // Retry on collision rather than silently overwriting someone else's link.
  let code = createCode();
  for (let attempt = 0; urls.has(code) && attempt < 10; attempt++) {
    code = createCode();
  }
  if (urls.has(code)) {
    throw new Error('could not allocate a unique code');
  }

  urls.set(code, normalised);
  hits.set(code, []);
  return code;
}

/** Returns undefined for an unknown code. Callers must handle that. */
export function resolve(code) {
  if (typeof code !== 'string') return undefined;
  return urls.get(code);
}

export function recordHit(code, referrer) {
  const entries = hits.get(code);
  if (!entries) return false;
  // Bounded: a link that gets hammered must not grow memory without limit.
  if (entries.length >= MAX_HITS_PER_CODE) entries.shift();
  entries.push({ at: Date.now(), referrer: referrer ?? null });
  return true;
}

/** Returns null for an unknown code so the caller can send a 404. */
export function stats(code) {
  const entries = hits.get(code);
  if (!entries) return null;
  return {
    code,
    url: urls.get(code),
    clicks: entries.length,
    lastClickAt: entries.length ? entries[entries.length - 1].at : null,
    referrers: entries.reduce((acc, hit) => {
      const key = hit.referrer ?? 'direct';
      acc[key] = (acc[key] ?? 0) + 1;
      return acc;
    }, {}),
  };
}

export function reset() {
  urls.clear();
  hits.clear();
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shorten, resolve, recordHit, stats, validateUrl, reset } from './store.js';

test('shortens and resolves a url', () => {
  reset();
  const code = shorten('https://example.com');
  assert.equal(resolve(code), 'https://example.com/');
});

test('rejects input that is not a usable url', () => {
  reset();
  assert.throws(() => shorten(''), /non-empty/);
  assert.throws(() => shorten(null), /non-empty/);
  assert.throws(() => shorten('not a url'), /valid URL/);
  assert.throws(() => shorten('ftp://example.com'), /http or https/);
  assert.throws(() => shorten('https://example.com/' + 'x'.repeat(3000)), /at most/);
});

test('validateUrl normalises rather than echoing input', () => {
  assert.equal(validateUrl('https://EXAMPLE.com'), 'https://example.com/');
});

test('resolve returns undefined for an unknown code', () => {
  reset();
  assert.equal(resolve('nope42'), undefined);
  assert.equal(resolve(undefined), undefined);
});

test('counts clicks and attributes referrers', () => {
  reset();
  const code = shorten('https://example.com');
  recordHit(code, 'https://news.example');
  recordHit(code, null);
  const s = stats(code);
  assert.equal(s.clicks, 2);
  assert.equal(s.referrers['https://news.example'], 1);
  assert.equal(s.referrers.direct, 1);
});

test('recording a hit on an unknown code fails softly', () => {
  reset();
  assert.equal(recordHit('nope42', 'x'), false);
});

test('stats for an unknown code is null, not a crash', () => {
  reset();
  assert.equal(stats('nope42'), null);
});

import http from 'node:http';
import { pathToFileURL } from 'node:url';
import { shorten, resolve, recordHit, stats } from './store.js';

const port = process.env.PORT || 4310;
const MAX_BODY_BYTES = 8192;

function json(res, status, payload) {
  res.writeHead(status, { 'content-type': 'application/json' });
  res.end(JSON.stringify(payload));
}

async function readBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > MAX_BODY_BYTES) throw new Error('request body too large');
  }
  return body;
}

const PAGE = `<!doctype html><meta charset="utf-8"><title>Shortener</title>
<style>body{font-family:system-ui;max-width:40rem;margin:4rem auto;padding:0 1rem}
input,button{font:inherit;padding:.5rem}code{background:#eee;padding:.2rem .4rem}</style>
<h1>URL shortener</h1>
<form onsubmit="go(event)"><input id=u size=40 placeholder="https://example.com"><button>Shorten</button></form>
<p id=out></p>
<script>
async function go(e){e.preventDefault();
 const r=await fetch('/api/shorten',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url:u.value})});
 const d=await r.json();
 out.innerHTML = r.ok ? '<a href="/'+d.code+'">/'+d.code+'</a> &middot; <a href="/api/stats/'+d.code+'">stats</a>' : 'Error: '+d.error;
}
</script>`;

const server = http.createServer(async (req, res) => {
  let url;
  try {
    url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
  } catch {
    return json(res, 400, { error: 'bad request line' });
  }

  if (req.method === 'POST' && url.pathname === '/api/shorten') {
    let payload;
    try {
      payload = JSON.parse(await readBody(req));
    } catch (err) {
      return json(res, 400, { error: `body must be valid JSON (${err.message})` });
    }
    try {
      const code = shorten(payload?.url);
      return json(res, 201, { code, short: `/${code}`, stats: `/api/stats/${code}` });
    } catch (err) {
      return json(res, 400, { error: err.message });
    }
  }

  if (url.pathname.startsWith('/api/stats/')) {
    const code = decodeURIComponent(url.pathname.slice('/api/stats/'.length));
    const found = stats(code);
    if (!found) return json(res, 404, { error: `no such code: ${code}` });
    return json(res, 200, found);
  }

  if (url.pathname === '/health') return json(res, 200, { ok: true });

  if (url.pathname !== '/' && url.pathname.length > 1) {
    const code = decodeURIComponent(url.pathname.slice(1));
    const target = resolve(code);
    if (!target) return json(res, 404, { error: `no such code: ${code}` });
    recordHit(code, req.headers.referer);
    res.writeHead(302, { location: target });
    return res.end();
  }

  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(PAGE);
});

// Only listen when run directly. Importing this from a test must not bind a
// port, or the suite fights itself for it.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  server.listen(port, () => console.log(`listening on ${port}`));
}

export { server };

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { server } from './server.js';
import { reset } from './store.js';

let base;

before(async () => {
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
});

after(() => server.close());

async function post(url) {
  return fetch(`${base}/api/shorten`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ url }),
  });
}

test('shortens a url and reports stats', async () => {
  reset();
  const res = await post('https://example.com');
  assert.equal(res.status, 201);
  const { code } = await res.json();

  const redirect = await fetch(`${base}/${code}`, { redirect: 'manual' });
  assert.equal(redirect.status, 302);
  assert.equal(redirect.headers.get('location'), 'https://example.com/');

  const stats = await (await fetch(`${base}/api/stats/${code}`)).json();
  assert.equal(stats.clicks, 1);
});

test('rejects a bad url with 400, not a 500', async () => {
  const res = await post('not-a-url');
  assert.equal(res.status, 400);
  assert.match((await res.json()).error, /valid URL/);
});

test('rejects a malformed body with 400', async () => {
  const res = await fetch(`${base}/api/shorten`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: '{oh no',
  });
  assert.equal(res.status, 400);
});

test('unknown code returns 404 on both redirect and stats', async () => {
  assert.equal((await fetch(`${base}/zzzz99`, { redirect: 'manual' })).status, 404);
  assert.equal((await fetch(`${base}/api/stats/zzzz99`)).status, 404);
});

